-- migrate:up
-- PULSE-HQ (owner, 23 Oct 2026): the first draft of Pulse HQ in the Pulse organisation (0944). The catalogue of every
-- Pulse feature, inventoried from the code, the docs and the lane reports on 23 Oct 2026 (117 features in 13
-- categories; all marked draft until the founder reviews each one), three sample offers (Agency Autopilot, Solar
-- Installer OS, Pulse Self-Hosted), seven ideas and a positioning and brand document, all drafts. Only where the Pulse
-- organisation exists; nothing is added twice.
do $$
declare v_org uuid; v_person uuid;
begin
  select id into v_org from pulse.org where handle = 'pulsehq';
  if v_org is null then return; end if;
  perform set_config('pulse.org_id', v_org::text, true);
  select m.person_id into v_person from pulse_priv.account_member m join pulse_priv.pulse_account a on a.id = m.account_id
   where a.handle = 'savuzo' and m.member_org = v_org;
  insert into pulse.hq_feature(org_id, key, category, name, promise, what, who, status, icon, proof, screenshot, sort, draft, created_by)
  select v_org, f.key, f.category, f.name, f.promise, f.what, f.who, f.status, f.icon, f.proof, f.screenshot, f.sort, true, v_person from (values
  ('focus-home', 'home', 'Focus and Max home', 'A calm view of what matters today, or every number when you want it', 'Leadership opens on Focus: a greeting, four key cards, a ranked Next up stack and what Pulse noticed. Max mode adds six headline numbers, invoiced against collected, money owed by age and the full queue.', 'Owners & leadership', 'live', 'House', '/home, /dashboard (Focus, Max)', '/home/eadev/ea-research/flow/reports/rel-shots/merge/dashboard-1440-light.png', 0),
  ('chat-home', 'home', 'Chat-first workspace', 'Start every day in one box that opens chats, pages and work instantly', 'On a computer Pulse opens on Chats: one box (@name, / commands, words or links), Needs you with tasks, steps and mentions, and Pip noticing when a message means a place and opening it beside the chat.', 'Every employee', 'live', 'MessagesSquare', '/ (app/page.tsx), /chats, chat-intent.ts', '/home/eadev/ea-research/ux/journeys/chat-shell/J1-1440-light.png', 1),
  ('sales-home', 'home', 'Role-based homes', 'Each role lands on its own home: sales queues, site visits, quotes to send', 'Admins choose per role whether people land on the dashboard or a sales home (urgent tasks, today''s calls, latest quotes); every role a person holds adds its own tiles of steps to do.', 'Sales teams', 'live', 'Target', '/dashboard (sales-home.tsx), /v1/flow/home, sales-home.ts', null, 2),
  ('my-desk', 'home', 'My desk', 'Your own day in one place: check-in, what is due, requests and pay', 'A personal home with five tabs (Today, Time, Growth, Requests, About me): check-in, what is due, attendance, leave, approvals, kudos from colleagues and your own attendance and payslip history.', 'Every employee', 'live', 'CalendarCheck', '/me, /me/approvals, self-history.ts, my-pulse.ts', '/home/eadev/ea-research/flow/reports/rel-shots/merge/me-1440-light.png', 3),
  ('leadership-people', 'home', 'Leadership people view', 'See value against cost, role seats and staffing gaps before they bite', 'Leadership sees each person''s value against cost (never ranked), role seats and who held them, staffing gaps (unowned work, overload, single points of failure) and the top people risks.', 'Owners & leadership', 'live', 'TrendingUp', '/leadership, people-value.ts', '/home/eadev/ea-research/ux/lifecycle/screens/staffing-1440-light.png', 4),
  ('updates-feed', 'home', 'Updates', 'Hand-off updates reach the right people, with read receipts', 'Updates addressed to people appear as a Home card and an Updates page, with a bell entry and a push to browser, desktop and phone, plus who has opened each one.', 'Every employee', 'live', 'Newspaper', '/updates, updates.ts', null, 5),
  ('role-briefs', 'home', 'Role briefs', 'A short, evidence-backed brief of what changed and what is missing for your role', 'Frozen, per-role briefs built from authorised evidence show positive changes and missing inputs, each with its receipt and an accountable action preview.', 'Every employee', 'live', 'FileText', '/briefs, briefs.ts', null, 6),
  ('page-insights', 'home', 'Insights drawer', 'Ask Pip about any page and get explained, sourced insights beside it', 'An insights drawer opens beside the page from Pip''s ''Ask Pip'' or the account menu, with explained findings and the place to act; domains without data say what intake is missing.', 'Every employee', 'live', 'Sparkles', 'apps/web/app/intelligence/rail.tsx, intelligence.ts', null, 7),
  ('command-search', 'home', 'Search everything', 'Ctrl+K finds any page, person, client, task, chat or policy in a moment', 'The command palette answers pages, settings, actions, people and clients instantly from the browser, then streams tasks, projects, chats, SOPs, policies and places from the server, respecting what each person may see.', 'Every employee', 'live', 'Search', 'Ctrl+K palette, search.ts', '/home/eadev/ea-research/flow/float-shots/after/admin-dashboard-1440-light-palette.png', 8),
  ('smart-notifications', 'home', 'Smart notifications', 'A bell that counts only what needs you and folds the rest', 'Notifications are ranked Urgent, Needs your action and For your information, folded by kind, with one-tap actions in the panel, mutes per kind, quiet hours and one daily HR digest.', 'Every employee', 'live', 'Bell', '/notifications, notices.ts, notification-policy.ts', '/home/eadev/ea-research/ux/polish2/after/notifications-folded-1440-light.png', 9),
  ('tasks-views', 'work', 'Tasks in every view', 'See work as a list, board, table, calendar, timeline or gallery', 'Tasks for any scope drawn as list, board, table, calendar, timeline or gallery, with saved views; one-line entry reads ''@Datup #Pulse fri !high'' into a task, and C creates one anywhere.', 'Every employee', 'live', 'CircleCheck', '/tasks, work-views.ts, task-quick.ts', '/home/eadev/ea-research/ux/tasks4a/after/v-company-calendar-1440-dark.png', 0),
  ('projects', 'work', 'Work projects', 'Run internal and fulfilment projects with a clear glance strip', 'Work projects hold tasks with a glance strip (done, open, blocked, finished, people), categories and owners, kept separate from client projects that live under Clients.', 'Managers & teams', 'live', 'FolderKanban', '/tasks?view=projects, /tasks/projects/[id], work.ts', '/home/eadev/ea-research/ux/tasks/07-work-projects-1440-light.png', 1),
  ('team-dashboard', 'work', 'Team dashboard', 'See what every pod is on, what is late and who is overloaded', 'A management dashboard of the team''s tasks by person and pod, with late and blocked work and drill-down into any person''s Work page.', 'Managers & leadership', 'live', 'Users', '/tasks?view=team, /tasks/people/[id]', '/home/eadev/ea-research/ux/tasks/01-team-dashboard-1440-dark.png', 2),
  ('task-focus', 'work', 'Task focus page', 'Every task answers what, by when and how, with what it unlocks', 'The task page shows a checklist from the notes, where it stands and its next action, what finishing it unlocks, the same work elsewhere and an unlock map of the biggest blockers.', 'Every employee', 'live', 'Crosshair', '/tasks/[id], /tasks/map, task-focus.ts', '/home/eadev/ea-research/ux/tasks-p0/after/unlock-map-1440-dark.png', 3),
  ('pip-task-plan', 'work', 'Plan it with Pip', 'Pip suggests the steps, the fastest path and who to ask', 'For any task Pip proposes steps, the fastest path, who to ask and a message ready to copy, plus suggested importance and effort with reasons; nothing is sent without you.', 'Every employee', 'live', 'Bot', 'ai/task-planner.ts, ai/task-scorer.ts', '/home/eadev/ea-research/ux/tasks-p0/after/task-pip-390-light.png', 4),
  ('task-review', 'work', 'Finish and review', 'Work counts only when someone else accepts it', 'Finishing checks open subtasks; the reviewer gives one quality rating or sends it back from wherever they are; there are no gameable value points.', 'Managers & reviewers', 'live', 'BadgeCheck', 'task-life.ts, /me/approvals', '/home/eadev/ea-research/ux/tasks4b/after/part1/task-accepted-1440-dark.png', 5),
  ('task-companion', 'work', 'Task companion', 'Pulse spots when a task is done and takes you straight to the right button', 'The task companion follows you with the task''s steps and signals, marks work done when the evidence shows it (with Undo), and ''Go there'' links glow the exact control on the target page.', 'Every employee', 'live', 'Navigation', 'task-companion.ts, apps/web/app/destinations', '/home/eadev/ea-research/ux/ux5b/after/companion-lit-1440-light.png', 6),
  ('work-pool', 'work', 'Work pool', 'Unowned work is proposed from your data and claimed by the right pod', 'Pulse proposes pool tasks from Drive folders, usual package steps and unowned tracker rows, routed to the pod that usually does them; leaders approve batches and set responsibility domains.', 'Owners & leadership', 'live', 'Inbox', 'pool-proposals.ts, work-domains.ts', '/home/eadev/ea-research/ux/tasks2/04-pool-1440-light.png', 7),
  ('outcomes', 'work', 'Outcomes', 'See what each person really delivered, week by week', 'Twelve weeks of accepted work by project and domain, tasks done, hours, extra work and streaks against a person''s usual week, plus a personal My week view; only work someone else accepted counts.', 'Managers & every employee', 'live', 'ChartColumn', '/tasks/outcomes, /my-week, outcomes.ts', '/home/eadev/ea-research/ux/tasks3/after/outcomes-extra-1440-light.png', 8),
  ('processes-library', 'flows', 'Processes library', 'Every way your company works, written and runnable, in one list', 'One library of processes (write-up plus steps) showing each one as written only, steps drafted or live with its runs; older SOPs, workflows and boards are read in so nothing is lost.', 'Every employee', 'live', 'Workflow', '/processes, /v1/flow/processes', '/home/eadev/ea-research/ux/flow/p1/processes-1440-light.png', 0),
  ('process-builder', 'flows', 'Process builder', 'Build a process as a simple list, or see it as a full-screen map', 'Build from about a dozen plain blocks (Start, Task, Collect, Meet, Write, Review, Decide, Wait, Message, AI, App action, Repeat, End) and your own saved blocks, as a list or full-screen map; Go live versions it.', 'Owners & leadership', 'live', 'GitBranch', '/processes/[id], flow/model.ts', '/home/eadev/ea-research/ux/flow-d/p2-ea-list-dev.png', 1),
  ('describe-process', 'flows', 'Describe it', 'Type how the work goes and Pip drafts the steps', 'Describe a process in plain words, or pick an existing write-up, and Pip drafts the steps with who does each and when, saying clearly what it could not tell.', 'Owners & leadership', 'live', 'Wand', '/processes/new, flow/describe.ts', null, 2),
  ('try-process', 'flows', 'Try it test runs', 'Rehearse a process as each person before anyone is affected', 'Run a draft as a test project with sample data, stepping into each role in turn, seeing alerts and due dates, fast-forwarding days, then throwing it away; nobody is notified.', 'Owners & leadership', 'live', 'FlaskConical', '/processes/[id]/try/[run]', '/home/eadev/ea-research/ux/flow-d/p3-try-solar-1.png', 3),
  ('runs', 'flows', 'Runs and live engine', 'Steps open as soon as their data exists, and every project reads in plain words', 'A readiness engine opens steps when inputs arrive and moves Day-N dates when inputs are late; each run shows stages, Pip''s line on what is late and who owes what, and Nudge to remind them.', 'Managers & leadership', 'live', 'ChartGantt', '/runs, /runs/[id], flow/registry.ts', '/home/eadev/ea-research/flow/reports/flow-a-shots/flowa-ea-run.png', 4),
  ('my-steps', 'flows', 'My steps', 'All your process steps across every project, worked in one place', 'Late, today, this week and later steps from every run, what others wait on you to type in and what is coming your way, plus Copy today''s update for the team.', 'Every employee', 'live', 'ListChecks', '/me/steps', '/home/eadev/ea-research/ux/flow/p5/step-1440-light.png', 5),
  ('step-work-screens', 'flows', 'Step work screens', 'Do the work inside the step, with its checklist, guide and Pip beside you', 'Each step opens a screen for its kind of work: a versioned document, a meeting with transcript, a review or decision, a collection, with typed records (personas, facts, offers, sites) and its SOP part beside it.', 'Every employee', 'live', 'PanelsTopLeft', '/steps/[id], flow/handlers.ts, flow/record-types.ts', '/home/eadev/ea-research/ux/flow-c/p1/doc-open-1440-light.png', 6),
  ('field-forms', 'flows', 'Field forms', 'Phone forms with geotagged photos, signatures and checklists', 'Build forms with camera-only photos stamped with time and place, signatures, locations, choices and checklists; filling one on a phone finishes the step and stores its answers on the run.', 'Field teams', 'live', 'ClipboardList', '/sops/forms, forms.ts', '/home/eadev/ea-research/ux/sop/screens/all/fill-photo-390-dark.png', 7),
  ('sop-import', 'flows', 'SOP import from Drive', 'Turn the SOP documents you already have into steps automatically', 'Pulse finds SOP-like documents in Drive and reads them into phases, steps, owners, KPIs and approvals with a confidence and evidence for each; leadership brings each in or edits it first.', 'Owners & leadership', 'live', 'FileInput', '/sops/drive, sop-parse.ts', '/home/eadev/ea-research/ux/sop/screens/all/drive-review-1440-light.png', 8),
  ('process-scorecard', 'flows', 'Scorecard and capacity', 'Know which processes run on time and who has room for the next one', 'The scorecard shows on-time steps, first-time confirmations, revisions and verdicts per process and person; capacity adds up focused hours of open steps against each person''s week.', 'Owners & leadership', 'live', 'Gauge', '/runs/scorecard, /runs/capacity', '/home/eadev/ea-research/ux/flow-c/p9/scorecard-1440-light.png', 9),
  ('process-libraries', 'flows', 'Reference libraries', 'Swipe files, reference videos and your word list, linked to the steps', 'Company libraries of swipe files, Drive reference videos, testimonials and a word list that every check reads, kept by leadership and linked from any step.', 'Owners & leadership', 'live', 'Library', '/processes/libraries', '/home/eadev/ea-research/ux/flow-c/p9/libraries-1440-dark.png', 10),
  ('industry-packs', 'flows', 'Industry packs', 'Set Pulse up for your industry, words and roles in one click', 'Packs for real-estate marketing, solar, agencies, consulting, clinics and developers add starter processes, roles and record types; rename clients, projects and runs, and steps go to role holders.', 'Owners & admins', 'live', 'Factory', '/settings?tab=industry, flow/packs.ts, flow/setup.ts', '/home/eadev/ea-research/ux/flow-e/p1-industry.png', 11),
  ('flow-apps', 'flows', 'App actions and triggers', 'Processes start from leads, forms or schedules and act in other apps', 'Start a process by hand, from a lead, a form, a schedule or a signed web address; App action steps create quotes and invoices, calendar events, Gmail or WhatsApp drafts, X-Ray calls and webhooks.', 'Owners & admins', 'live', 'PlugZap', '/settings?tab=apps, flow/apps.ts', '/home/eadev/ea-research/ux/flow-e/p3-apps.png', 12),
  ('team-chats', 'chats', 'Team chats and groups', 'Direct messages, pod channels and groups with files, built into your work', 'Direct and group chats with pod and team channels, file sharing, reply quotes, edit and delete windows, presence and status, and duplicate channels quietly merged.', 'Every employee', 'live', 'MessageCircle', '/chats, /groups, chats.ts', '/home/eadev/ea-research/ux/chats/screens/01-chat-list-1440-dark.png', 0),
  ('chat-side-panel', 'chats', 'Chat side panel', 'Open any page, Doc or link beside the conversation without leaving it', 'A tabbed side panel opens Pulse pages, Google Docs, Sheets, Slides and Drive files, or any web link next to the chat; tabs persist, and on a phone it is a bottom sheet.', 'Every employee', 'live', 'PanelRight', 'apps/web/app/chats/workspace/panel.tsx', '/home/eadev/ea-research/ux/journeys/chat-shell/J3-1440-light.png', 1),
  ('chat-tasks', 'chats', 'Work from chat', 'Give, take and track tasks right inside the conversation', 'Type ''@rila draft it by Thu'' to send a task card; the receiver takes, declines or asks on the card; /tasks, /projects and /steps show a group''s work; files become tasks in one tap.', 'Every employee', 'live', 'MessageSquareText', 'chat-work.ts, /api/v0/chats/:id/work', '/home/eadev/ea-research/flow/reports/chat-work-shots/p1-j2-offer.png', 2),
  ('voice-messages', 'chats', 'Voice messages', 'Hold to talk, with played receipts and 2x playback', 'Record voice notes hands-free or hold-to-talk, play them with a seekable waveform at up to 2x and see when yours was heard; on-server transcription is built and switched off until enabled.', 'Every employee', 'live', 'Mic', 'chat-voice.ts, PULSE_VOICE_TRANSCRIPTS', null, 3),
  ('calls', 'chats', 'Voice and video calls', 'Call a colleague or a group of up to eight without leaving Pulse', '1:1 and group voice or video calls from any chat or /call, ringing across browser tabs and devices, minimising to a pill while you work, with call history kept in the chat.', 'Every employee', 'live', 'Phone', 'calls.ts, apps/web/app/calls', null, 4),
  ('email-inbox', 'chats', 'Email reader', 'Read your Gmail inside Pulse, fast and safely', 'A Gmail-class read-only reader for each person''s own mailbox, cached for instant revisits, with newsletters rendered in a sandbox and tracking links unwrapped.', 'Every employee', 'live', 'Mail', '/inbox, /communication, email.ts', '/home/eadev/ea-research/ux/chats/screens/12-email-inbox-1440-light.png', 5),
  ('ai-employees', 'chats', 'AI employees', 'Add AI team members who take tasks and report back in chat', 'Add an AI employee like a person (role, pod, manager) with its runtime, model, token budget, tools and memory; leaders give it tasks in chat and it posts results for approval.', 'Owners & leadership', 'live', 'Bot', '/people/ai/[id], agents.ts, services/coworker', '/home/eadev/ea-research/ux/journeys/chat-work/shots/J7-1440-light-2-profile.png', 6),
  ('pip-assistant', 'chats', 'Pip companion', 'A friendly helper on every page for your day, alerts and quick actions', 'Pip floats on every page with one menu: check in or out, the most urgent items, notifications, Ask Pip, new task or project, do not disturb; it moves aside from buttons by itself.', 'Every employee', 'live', 'Smile', 'packages/companion/src/pip.js, shell', '/home/eadev/ea-research/flow/float-shots/after/admin-dashboard-1440-light-pip-hover.png', 7),
  ('pip-in-steps', 'chats', 'Pip writing assistant', 'Draft, critique and check work against your own SOPs and facts', 'Inside a step Pip outlines from the write-up, critiques against what good looks like, checks words to avoid, unconfirmed claims and stale offers, and pulls facts from transcripts; you decide.', 'Every employee', 'live', 'PenLine', 'ai/flow-assist.ts, /steps/[id]', null, 8),
  ('whatsapp-import', 'chats', 'WhatsApp history import', 'Bring past WhatsApp group history into the right Pulse conversation', 'Admins preview a WhatsApp text export in the browser, map senders to colleagues and import it into a conversation readable only by its members; message text is never logged.', 'Owners & admins', 'beta', 'Import', '/chats/import, PULSE_CHAT_IMPORT', null, 9),
  ('whatsapp-names', 'chats', 'WhatsApp sender matching', 'Decide once who each WhatsApp sender is, privately', 'A private screen where leadership and HR load names from their own exports (only names and counts leave the computer) and match each sender to a colleague before any import.', 'HR & leadership', 'live', 'UserSearch', '/review-data/whatsapp-names, chat-names.ts', null, 10),
  ('team-directory', 'people', 'Team and profiles', 'Everyone''s profile, work and contact details, with AI members shown apart', 'Team lists people and AI employees with profiles holding My info, documents and history, plus their projects and deliveries found from Drive and tracker evidence for managers to confirm.', 'Every employee', 'live', 'Users', '/people, /people/[id], records.ts, people-work.ts', '/home/eadev/ea-research/ux/people/screens/browser/profile-1440-light.png', 0),
  ('org-chart', 'people', 'Org chart', 'Who reports to whom, proposed from real work and confirmed in a click', 'An org chart with pods and departments; Pulse proposes reporting lines from rosters, roles, Workspace groups and who gives whom tasks, and HR confirms each or all above a confidence.', 'HR & leadership', 'live', 'Network', '/people/org, org.ts', '/home/eadev/ea-research/ux/tasks3/after/org-1440-dark.png', 1),
  ('hr-desk', 'people', 'HR desk', 'HR''s whole day in five tabs: people, time, approvals, pay and policy', 'An HR desk with who is in, people, time, approvals and pay and policy; HR requests and corrections are routed to the right approver with reminders and an audit trail.', 'HR', 'live', 'BriefcaseBusiness', '/hr, /hr/help, hr.ts, hr-flow.ts', '/home/eadev/ea-research/ux/layout/after-fixed/hr-1366x768-light.png', 2),
  ('auto-attendance', 'people', 'Automatic attendance', 'Check-ins that happen by themselves when you reach the office', 'With consent, Pulse checks people in and out from office Wi-Fi, location and device signals and records breaks; HR sees only days it could not settle, with Confirm, Fix or Dismiss.', 'Every employee', 'live', 'Fingerprint', 'companion-presence.ts, attendance-exceptions.ts', '/home/eadev/ea-research/ux/ux5a/after/runner/me-attendance-1440-light.png', 3),
  ('leave-shifts', 'people', 'Leave, holidays and shifts', 'Apply, approve and balance leave against your company''s own rules', 'Leave types, balances, adjustments and holidays, regularisations, shift patterns with grace times, and rules HR confirms before they apply.', 'Every employee & HR', 'live', 'CalendarRange', '/shifts, /api/v0/leave, hr-rules.ts', null, 4),
  ('hr-policies', 'people', 'Policies and acknowledgements', 'Publish policies and know who has read them', 'HR publishes versioned policies, including Word files read safely into text, and employees acknowledge the exact version. A browser Word editor with a fidelity check is built but off.', 'HR', 'live', 'ScrollText', '/hr (Policies), policy-docx.ts, policy-word.ts', null, 5),
  ('employee-onboarding', 'people', 'Employee onboarding', 'New joiners set themselves up on a phone in about three minutes', 'A self-serve first run for details, emergency contact, bank details with IFSC lookup, documents (Aadhaar masked as the law requires), the app, notifications and office-presence consent.', 'New employees & HR', 'live', 'UserPlus', '/welcome, presence-onboard.ts, onboarding-model.ts', '/home/eadev/ea-research/ux/people/screens/browser/onboard-bank-1440-light.png', 6),
  ('joining-leaving', 'people', 'Joining and leaving', 'Checklists for every joiner and leaver, with hand-overs suggested', 'Stages from candidate to left, joining and leaving checklists Pulse proposes and HR confirms, review of people who have probably left, and hand-over of work, projects and reports.', 'HR & leadership', 'live', 'ArrowLeftRight', '/hr/moves/[id], lifecycle.ts', '/home/eadev/ea-research/ux/lifecycle/screens/moves-1440-dark.png', 7),
  ('pay-records', 'people', 'Pay from offer to exit', 'Offers, letters, salary, claims and payslips in one sealed record', 'Pay from offer to exit: offers by private link, letters, approved salary versions, one-time items and claims, with amounts sealed and reads logged; each person sees their own on My pay.', 'Founders & HR', 'live', 'Banknote', '/people/pay, /me/pay, comp.ts', null, 8),
