  ('people-cost', 'finance', 'People cost and runway', 'Budget against actual payroll, runway and what-if scenarios', 'This month''s payroll, budget against actual by month and pod, committed pay and planned roles, cash forecast with people cost, runway and what-if scenarios that never touch records.', 'Founders & HR', 'live', 'PiggyBank', '/finance/people-cost, people-cost.ts', '/home/eadev/ea-research/ux/lifecycle/screens/finance-people-1440-light.png', 3),
  ('billing-documents', 'finance', 'Billing and invoices', 'Quotations, proformas, tax invoices and credit notes from draft to paid', 'Numbered GST quotations, proformas, invoices and credit notes from draft to paid with approvals, PDF and Word output, client acceptance by private link, and a full log.', 'Founders & finance', 'live', 'ReceiptText', '/erp, /erp/documents, /accept/[token], erp.ts', null, 4),
  ('catalogue', 'finance', 'Catalogue and inventory', 'Services, packages and stock in one place, with price history', 'A catalogue of services, products and packages with parts, versions and price history, plus inventory of physical items with every movement kept and low-stock alerts.', 'Finance & sales teams', 'live', 'Package', '/erp/catalog, /erp/inventory', null, 5),
  ('billing-templates', 'finance', 'Templates and exports', 'Your own templates and numbering, exported to Tally or Zoho Books', 'Templates with live preview, numbering, taxes, optional fields and a billing industry pack; issued documents export as Tally XML, Zoho Books CSV or a sales register.', 'Finance', 'live', 'LayoutTemplate', '/erp/templates, /erp/settings, erp-exports.ts', null, 6),
  ('quote-followups', 'finance', 'Quote follow-ups', 'Every sent quotation gets a follow-up task until the customer answers', 'Sent quotations get their next follow-up date, a task and notice for the salesperson and a record of the customer''s answer; quotes can be shared and converted safely from a phone.', 'Sales teams', 'live', 'PhoneForwarded', '/quotes/[id], quote-followups.ts', null, 7),
  ('ad-spend', 'finance', 'Ad spend and growth', 'See ad spend, client growth and project calls in one research view', 'Research views from imported datasets show ad spend, client growth and per-project calls, with aggregates for everyone and detail for the responsible team.', 'Owners & leadership', 'live', 'Megaphone', '/api/v0/research, /api/v0/money/ad-spend', null, 8),
  ('clients-crm', 'clients', 'Clients', 'Every client with their projects, deliveries, money and history', 'Client records with their projects, deliveries read from Drive, visits, money for those with access and a timeline; edits are locked against the next sync and logged.', 'Sales & account teams', 'live', 'Building2', '/clients, /clients/[id], /projects, /deliveries', '/home/eadev/ea-research/ux/tasks/11-client-projects-1440-dark.png', 0),
  ('contacts', 'clients', 'Contacts', 'Each contact''s clients, projects, conversations and files on one profile', 'Contacts typed by your own categories, each with a profile of clients and projects, deliveries, team chats and your mail with them, files, notes, money and one timeline.', 'Sales & account teams', 'live', 'BookUser', '/contacts, /contacts/[id]', '/home/eadev/ea-research/ux/people/screens/browser/contact-1440-light.png', 1),
  ('client-identity', 'clients', 'Client master and data care', 'One clean record per client, with duplicates merged safely', 'A client master that finds duplicates by verified identifiers and merges them with reviewed decisions and undo; stewardship corrects addresses, links and map pins with history.', 'Admins & finance', 'live', 'Merge', '/clients?tab=master, /contacts/identity, /stewardship/[entity]/[id]', null, 2),
  ('acquisition', 'clients', 'Acquisition desk', 'Every enquiry from source to booking, with honest cost per lead', 'Lead sources, reviewed intake from forms, landing pages and CRMs via signed webhooks, distinct enquiries, contact attempts, visits and outcomes, and cost per lead only when attribution is complete.', 'Sales teams & leadership', 'live', 'TrendingUp', '/acquisition, acquisition-routes.ts', null, 3),
  ('site-visits', 'clients', 'Site visits', 'Configurable site visits with photo fields and notes per customer', 'Companies define visit types and the photo fields each asks for as versioned settings; staff open and submit visits from the customer page with notes and private site photos.', 'Field & sales teams', 'live', 'MapPinned', '/clients/[id]/visits, site-visits.ts', null, 4),
  ('client-portal', 'clients', 'Client portal', 'Clients sign in to see their deliveries, approvals and billing', 'A separate client sign-in where clients see what was delivered, comment, accept or ask for changes, view linked invoices and raise support, only for projects they are granted.', 'Clients', 'live', 'DoorOpen', '/portal, /portal/login, portal-routes.ts', null, 5),
  ('delivery-workbench', 'clients', 'Delivery workbench', 'Phased delivery with internal review, client sign-off and support', 'Deliver client work in phases and parallel tracks with readiness, blockers, exact internal review, client acceptance or change requests, linked invoices and owned support.', 'Account & delivery teams', 'live', 'Truck', '/delivery, /delivery/access, /delivery/support', null, 6),
  ('relationships-graph', 'clients', 'Relationship graph', 'Who works with whom across projects, developers and partners, with sources', 'Projects, developers, channel partners, clients and contacts joined by typed relationships with source, dates and status; imported links stay proposals until a named reviewer confirms.', 'Leadership & account teams', 'beta', 'Share2', '/relationships, relationships.ts, PULSE_RELATIONSHIPS', '/home/eadev/ea-research/ux/relationships/graph-1440-light.png', 7),
  ('pulse-map', 'clients', 'Pulse Map', 'Every development on a map, with money, markets and white space', 'Each development as a pin with how precisely its place is known, engagements, shoots, market prices, travel time and white space, and money by place for leadership with finance access.', 'Owners & leadership', 'live', 'Map', '/map, map.ts', null, 8),
  ('talent-board', 'clients', 'Talent and models board', 'Know which models and talent bring results, with the evidence', 'A ranked board and profile per model or talent from shoots, projects, clients and videos, with method and confidence shown; costs only for leadership with finance access.', 'Creative & leadership', 'live', 'Star', '/contacts/models, talent.ts', null, 9),
  ('creative-strategy', 'creative', 'Creative Strategy app', 'Run creative sprints on a clock that moves when inputs are late', 'CS Home shows a strategist''s Day-1 alerts, overdue and due work; each sprint holds the package, approver, critical inputs and dated deliverables that shift by each day an input is late.', 'Creative strategists', 'beta', 'Lightbulb', '/creative, /creative/sprints/[id], PULSE_CREATIVE', null, 0),
  ('designers-board', 'creative', 'Designers board', 'See each designer''s weekly deliveries by type, and why', 'A weekly board of design deliveries per designer and type, with explanations of how each was counted and designers able to claim their work.', 'Creative leads', 'live', 'Palette', '/designers, /v1/designs/claims', null, 1),
  ('asset-tracker', 'creative', 'Asset tracker', 'Every deliverable with its own ID, versions and journey to live', 'Deliverables carry an Asset ID and timeline from draft to live with each date, review verdicts, counted revisions, version bumps, and script, videographer and editor notes.', 'Creative teams', 'live', 'Clapperboard', '/steps/[id] (Asset)', '/home/eadev/ea-research/ux/flow-c/p1/asset-1440-light.png', 2),
  ('media-review', 'creative', 'Media review', 'Comment on a cut at the exact moment and track every change', 'Play video versions in Pulse, comment at a timestamp and turn comments into owned changes; share drafts with clients, record each round of feedback and log the confirmation.', 'Creative teams & reviewers', 'live', 'Film', '/steps/[id] (Media review, Share for review)', null, 3),
  ('shoot-planning', 'creative', 'Shoot planning', 'Plan a shoot and write the call sheet in minutes', 'Plan a shoot or visit with date, call time, place, people, shot list and equipment, then write a call sheet to copy or print, with consent and casting alongside.', 'Creative & production teams', 'live', 'Camera', '/steps/[id] (Plan a shoot)', null, 4),
  ('brand-sheet', 'creative', 'Brand sheet', 'Your mark, Pip and every app icon, seen as each platform shows them', 'A brand sheet with mark directions, the mark from favicon to app tile, Pip''s moods and every app icon as the platforms show it; the company logo is set in Settings.', 'Owners & admins', 'beta', 'Brush', '/brand, brand.ts', '/home/eadev/ea-research/ux/notify/screens/1440-light-08-brand-directions.png', 5),
  ('xray-connect', 'xray', 'Sales X-Ray connection', 'Each salesperson connects their own Sales X-Ray account securely', 'Each person connects their own Sales X-Ray account by OAuth with PKCE; tokens are sealed and bound to the person, and nothing from Sales X-Ray is copied into Pulse.', 'Sales teams', 'beta', 'PlugZap', '/apps/sales-xray, sales-xray.ts, PULSE_SALES_XRAY', '/home/eadev/ea-research/ux/flow-e/p3-sheet-xray.png', 0),
  ('xray-calls-leads', 'xray', 'Calls, leads and Ask', 'Read your analysed calls and leads, and ask about them in plain words', 'Each person reads their calls with the facts found in them and their leads, live from Sales X-Ray, and asks Pulse questions answered read-only through Sales X-Ray''s MCP server.', 'Sales teams', 'beta', 'PhoneCall', '/apps/sales-xray (Calls, Leads, Ask)', null, 1),
  ('xray-in-processes', 'xray', 'Calls in processes', 'Drop a call''s summary, objections and score straight into a project step', 'A Sales X-Ray step lists your analysed calls and ''Use this call'' puts its summary, asks, objections, promises and score on the step; process step names go back as lead-stage suggestions.', 'Sales teams', 'beta', 'Radar', 'flow/apps.ts (sales_xray), /processes', '/home/eadev/ea-research/ux/flow-e2e-e/28-d-priya-xray-done.png', 2),
  ('pulse-network', 'network', 'Pulse Network', 'Companies, leaders and their AI agents posting and handing off work', 'A shared network feed, direct messages and channels with people and agents, and hand-offs from asked to done between companies; only what someone posts leaves the company. Leaders only.', 'Owners & leadership', 'beta', 'Globe', '/network, network.ts', null, 0),
  ('org-switcher', 'network', 'One account, many organisations', 'One Pulse account across every organisation you work with', 'One account linked to each organisation, a switcher (Ctrl+Shift+O) with no new sign-in, and invitations for team members, freelancers or clients by handle or private 14-day link.', 'Every employee & freelancers', 'live', 'Repeat', '/orgs, /join, accounts.ts', '/home/eadev/ea-research/ux/journeys/J9/01-owner-switcher.png', 1),
  ('start-own-pulse', 'network', 'Start your own Pulse', 'Anyone can start their own organisation in one step', 'Name it, pick a handle and an industry pack and you own a new organisation, then switch back any time.', 'Freelancers, clients & new companies', 'live', 'Rocket', '/orgs/new', null, 2),
  ('portable-profile', 'network', 'Portable profile', 'Your profile, skills and badges travel with you between organisations', 'A profile that travels with the account: headline, skills, links, badges organisations give, highlights from finished work, and per-organisation sharing; no company records travel.', 'Every employee & freelancers', 'live', 'IdCard', '/orgs/profile', null, 3),
  ('licences-register', 'network', 'Licences register', 'Every licensed Pulse install, its key and whether it is up to date', 'A central register of every organisation licensed to run Pulse, with handle, licence key and organisation ID, checking each install live for the release it runs.', 'Platform owner', 'beta', 'KeyRound', '/orgs/licences, licences.ts', null, 4),
  ('desktop-app', 'apps', 'Desktop app', 'Check in, take breaks and see your day from the tray or menu bar', 'A Windows and Mac app with a tray or menu-bar panel (Ctrl+Alt+P) to check in, break and check out, with a live timer, next shift, requests waiting, Pip and reminders.', 'Every employee', 'live', 'Monitor', 'apps/desktop (Tauri, v1.0.2), tools/desktop-publish', null, 0),
  ('phone-app', 'apps', 'Phone app', 'Pulse on Android with push alerts, camera and GPS site photos', 'The Pulse app for Android (and iPhone builds) wraps the web app with push notifications, verified app links, offline recovery, GPS site photos and builds per company address.', 'Every employee', 'live', 'Smartphone', 'apps/mobile (Capacitor, 1.1.4)', null, 1),
  ('chrome-extension', 'apps', 'Chrome companion', 'Your check-in panel one click away in the browser toolbar', 'A Chrome extension popup with check in, break, check out, timer, Pip and a status badge; optional work-site context stays opt-in.', 'Every employee', 'beta', 'Chrome', 'apps/chrome-extension (v1.0.0)', null, 2),
  ('activity-collector', 'apps', 'Opt-in work activity', 'Optional, privacy-first focus and idle summaries for approved work apps', 'An opt-in desktop collector records only focus and idle summaries for allow-listed work apps after a published notice; no screenshots, keystrokes or window titles are uploaded.', 'Employees who opt in', 'beta', 'Activity', 'apps/desktop/core, docs/native-apps/round-14.md', null, 3),
  ('push-notifications', 'apps', 'Push everywhere', 'Alerts on phone, desktop and browser, even with Pulse closed', 'Browser web push, Android push and desktop notices, with incoming calls ringing at high priority and a single chip to turn notifications on.', 'Every employee', 'live', 'BellRing', 'web-push.ts, native-push.ts', null, 4),
  ('install-guides', 'apps', 'Install, pairing and devices', 'Install Pulse on any device and sign in with your Pulse account', 'Public install pages per platform, a pairing flow where the app shows a code you approve, and an admin view of each device''s connection health plus in-app feedback with screenshots.', 'Every employee', 'live', 'Download', '/apps, /apps/[platform], /connect, /settings?tab=devices', null, 5),
  ('organisation-settings', 'admin', 'Organisation settings', 'Name, logo, time zone, pods and teams, managed in one place', 'Admins manage the organisation''s name, logo, time zone, pods, teams and the admin and HR roles; every change is written to the record history.', 'Admins', 'live', 'Settings', '/settings?tab=organisation, settings.ts, brand.ts', null, 0),
  ('roles-permissions', 'admin', 'Roles and permissions', 'Decide who can see and do what, enforced in the database', 'Roles and permissions plus a ''Who can do what'' matrix for work; row-level security in the database enforces the same rules the screens show.', 'Admins', 'live', 'ShieldCheck', '/settings?tab=roles, /settings?tab=work-rules', '/home/eadev/ea-research/ux/tasks/12-who-can-do-what-1440-dark.png', 1),
  ('screens-per-role', 'admin', 'Screens and menus per role', 'A simpler menu for each role, without changing anyone''s access', 'Admins hide screens and menu entries per role and choose each role''s home; hidden screens leave menus and search, while core screens always stay.', 'Admins', 'live', 'EyeOff', '/settings (Modules, Screens and menu), screens.ts', null, 2),
  ('module-switches', 'admin', 'Module switches', 'Turn whole modules on or off for your company', 'Companies switch off modules such as Designers, Map, Acquisition, Chats, Money or HR; an off module disappears from navigation and its API answers as if absent.', 'Admins', 'live', 'ToggleRight', '/settings (Modules), modules.ts', '/home/eadev/ea-research/ux/tenant/23-datup-settings-modules.png', 3),
  ('sign-in-security', 'admin', 'Sign-in and security', 'Google, username or one-time link sign-in, with two-step for sensitive roles', 'Per-company Google sign-in, quiet sign-in, passwords, usernames and one-time links; two-step sessions for sensitive roles, new-device notices and admin-ended sessions.', 'Admins & every employee', 'live', 'LogIn', '/login, /account, account-security.ts', '/home/eadev/ea-research/ux/people/screens/browser/account-access-1440-light.png', 4),
  ('audit-log', 'admin', 'Audit log', 'Who did what, to which record, and when', 'An audit log filterable by actor, resource, action and date, alongside per-record change history and logged reads of sensitive data such as salaries.', 'Admins & leadership', 'live', 'FileClock', '/audit', null, 5),
  ('review-data', 'admin', 'Review data and health', 'Clean up your data by deciding the most important suggestions first', 'Pending suggestions ranked by impact and confidence, decided group by group; Settings shows each source''s freshness and Drive root health so nobody trusts stale data.', 'Admins & HR', 'live', 'ScanSearch', '/review-data, /settings?tab=data-health', null, 6),
  ('sealed-documents', 'admin', 'Sealed personal data', 'ID documents and bank details encrypted so even the database cannot read them', 'Government ID files, bank details and pay amounts are sealed with per-file keys outside the database, with key rotation; Aadhaar and PAN are masked as Indian law requires.', 'Admins & HR', 'live', 'FileLock', 'document-keys.ts, onboarding-model.ts', null, 7),
  ('company-setup', 'admin', 'Company setup wizard', 'Set up a new company step by step, isolated and on its own address', 'Set up a company''s details, brand, first admin, people, pods and roles, modules and industry, run an isolation check and open it for sign-in; companies start in trial until activated.', 'Platform owner', 'live', 'Building', '/companies, /companies/[id], tenants.ts', '/home/eadev/ea-research/ux/tenant/11-isolation-check.png', 8),
  ('data-import', 'admin', 'Data importers', 'Bring in existing projects, tasks and finance sheets safely', 'Importers for Ops Hub projects and tasks, finance tool sheets and HR openings run as a dry run first and keep a ledger of before-values.', 'Admins', 'live', 'DatabaseZap', '/opshub, docs/ops/TOOLS-IMPORT.md', null, 9),
  ('api-v1', 'platform', 'Pulse API', 'A scoped, audited API for your apps and AI agents', 'API v1 for app keys, AI employee keys and personal tokens, with area scopes, paging, rate limits, idempotent writes and an audit receipt per call; admins issue and revoke scoped, expiring keys.', 'Developers & partners', 'live', 'Code', '/api/v1, v1.ts, integration-keys.ts', null, 0),
  ('developers-page', 'platform', 'Developer portal', 'API reference and a token-only try-it page for builders', 'A Developers page with quickstarts, the v1 reference and a try-it console that uses only your API key.', 'Developers & partners', 'live', 'Terminal', '/developers', null, 1),
  ('partner-agent-api', 'platform', 'Partner agent API', 'Let your own agents read the catalogue and leads and draft quotes', 'Service keys let a company''s agents read its catalogue, clients and leads, look up by phone, create draft quotes and notify only the salesperson.', 'Developers & partners', 'live', 'Handshake', 'service-quotes.ts, service-phone.ts, catalog.ts', null, 2),
  ('webhooks', 'platform', 'Signed webhooks', 'Tell your other systems the moment something changes', 'Signed webhook posts for quotation status changes through a durable event outbox, and process webhook steps with the secret shown once.', 'Developers & partners', 'live', 'Webhook', 'install-event-delivery.ts, flow/apps.ts', null, 3),
  ('company-connectors', 'platform', 'Company connectors', 'Each company connects its own sources with its own credentials', 'Admins preview, install, grant and revoke connectors for their company only, including Pulse''s Drive reader or their own plugin pushing signed batches; nothing is read until enabled.', 'Admins', 'beta', 'Cable', '/settings (Connected sources), connectors.ts, PULSE_CONNECTORS', null, 4),
  ('drive-sync', 'platform', 'Google Drive sync', 'Projects, deliveries and documents kept current from your Drive', 'An index of Drive project folders feeds projects, deliveries and SOP discovery; a direct changes feed and text capture from approved roots are built behind switches.', 'Admins', 'beta', 'HardDrive', 'drive-changes.ts, drive-text.ts, PULSE_DRIVE_CHANGES', null, 5),
  ('self-hosted', 'platform', 'Self-hosted Pulse', 'Run Pulse on your own server, with one-command updates and rollback', 'An install kit with backup, restore drill and an update script that migrates, health-checks and rolls back on failure; releases come from a train that runs the full test gate first.', 'IT teams & licensees', 'live', 'Server', 'docs/ops/tenant-own-server, docs/ops/RELEASE-TRAIN.md', null, 6),
  ('pulse-cli', 'platform', 'Pulse CLI', 'Script Pulse from the terminal with your API key', 'A command-line client to sign in, list operations and call any API operation with idempotency keys and paging; listed as planned on the Developers page.', 'Developers', 'idea', 'SquareTerminal', '/developers (CLI, Planned)', null, 7),
  ('pulse-mcp', 'platform', 'Pulse MCP server', 'Connect AI assistants to Pulse with only the tools your key allows', 'An MCP endpoint over Streamable HTTP at /api/v1/mcp listing only the tools a key permits; listed as planned on the Developers page.', 'Developers & AI teams', 'idea', 'Unplug', '/developers (MCP, Planned)', null, 8),
  ('whatsapp-client-chat', 'chats', 'WhatsApp client chat', 'Talk to clients on WhatsApp from Pulse through your business number', 'Client conversations through a dedicated business number on WhatsApp''s Cloud API with approved templates and opt-in; designed and decided, not yet built.', 'Account teams', 'idea', 'MessageSquareShare', 'docs/spec/11-whatsapp-client-chat.md', null, 11)
  ) as f(key, category, name, promise, what, who, status, icon, proof, screenshot, sort)
