    values (v_org, 'Agency Autopilot', 'draft', 'Founder-led creative and marketing agencies in India, 15 to 80 people, delivering client work through WhatsApp groups, sheets and a project tool nobody updates. The founder is the delivery system.', 'Every client deliverable on time and every person accountable, and the founder stops chasing: the agency runs the same week whether or not the founder is in the room.', 9, 7, 3, 3, '["Your agency running on Pulse in 30 days: clients, projects, tasks, chats and attendance in one app", "Your SOPs turned into runnable processes, with each step owned and timed", "A client portal where clients see deliveries, approve and pay", "A founder home that shows what is late, who is overloaded and what is unpaid, without asking", "AI employees that take routine tasks and report back in chat"]'::jsonb, '[{"name": "Done-for-you SOP import", "value": 75000, "why": "We turn the Google Docs you already have into live processes, so nobody starts from a blank page."}, {"name": "WhatsApp history import", "value": 25000, "why": "Past client conversations land in the right Pulse chat, so no context is lost on day one."}, {"name": "Founder control-room setup call", "value": 20000, "why": "A 90-minute session to set the numbers you check every morning."}, {"name": "Creative Strategy app (early access)", "value": 30000, "why": "Run creative sprints on a clock that moves when client inputs are late."}]'::jsonb,
      'Thirty-day on-time guarantee: if by day 30 you cannot see every live client delivery, its owner and its due date in Pulse, month two is free and we keep working until you can.', 'We launch five agencies a month, because every launch gets a white-glove setup team.', 'Founding-customer pricing is locked for life for agencies that start before 31 December 2026.', '{"magnet": "Autopilot", "avatar": "Agency", "goal": "On-time delivery without the founder chasing", "interval": "in 30 days", "container": "Launch", "tagline": "Agency Autopilot: on-time delivery in 30 days, without the founder chasing."}'::jsonb, '[{"label": "An operations manager to chase delivery (per month)", "amount": 120000}, {"label": "Project tool + chat + HRMS + payroll + invoicing stack for 40 people (per month)", "amount": 45000}, {"label": "One lost retainer from a missed deadline (per month)", "amount": 150000}]'::jsonb, 'INR', 59999,
      'month', 'For founder-led agencies drowning in WhatsApp follow-ups, Agency Autopilot is the one app where client work, people and money run on their own. Unlike project tools that need a manager to keep them true, Pulse knows what was delivered from the work itself.', 'Confident and calm. Lead with the founder getting their evenings back. Show the founder home and the client portal first. Avoid the word "platform".', '[{"key": "studio", "name": "Studio", "price": 24999, "seats": 15, "blurb": "For a small studio replacing chats and sheets.", "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications"]}, {"key": "agency", "name": "Agency", "price": 59999, "seats": 50, "blurb": "Processes, client portal, payroll and AI employees.", "highlight": true, "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications", "processes-library", "process-builder", "runs", "my-steps", "sop-import", "clients-crm", "contacts", "delivery-workbench", "client-portal", "media-review", "asset-tracker", "designers-board", "team-dashboard", "outcomes", "task-review", "billing-documents", "finance-overview", "hr-desk", "payroll", "ai-employees", "updates-feed", "role-briefs"]}, {"key": "network", "name": "Network", "price": 149999, "seats": null, "blurb": "Several brands or offices, finance desk, API and self-hosting.", "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications", "processes-library", "process-builder", "runs", "my-steps", "sop-import", "clients-crm", "contacts", "delivery-workbench", "client-portal", "media-review", "asset-tracker", "designers-board", "team-dashboard", "outcomes", "task-review", "billing-documents", "finance-overview", "hr-desk", "payroll", "ai-employees", "updates-feed", "role-briefs", "creative-strategy", "shoot-planning", "whatsapp-import", "leadership-people", "people-cost", "ca-desk", "org-switcher", "api-v1", "webhooks", "self-hosted", "module-switches", "screens-per-role"]}]'::jsonb, '#6b4cf0', 0, true, v_person);
    insert into pulse.hq_offer(org_id, name, status, icp, dream_outcome, v_dream, v_likelihood, v_time, v_effort, deliverables, bonuses, guarantee, scarcity, urgency,
