    values (v_org, 'Pulse Self-Hosted', 'draft', 'Companies of 50 to 500 people that must keep their data on their own servers (IT policy, clients'' contracts or regulation), and agencies that want Pulse under their own brand for their clients.', 'Your own Pulse on your own server: your data never leaves, your brand on every screen, and new releases arrive with one command.', 8, 8, 3, 4, '["Pulse installed on your server, on your domain, with your logo and colours", "One-command updates from the Pulse release channel, with rollback", "Your licence in the central register: release and health checked live", "Your people, freelancers and clients keep one Pulse account across organisations", "Quarterly roadmap call with the Pulse team"]'::jsonb, '[{"name": "Installation and hardening by our team", "value": 150000, "why": "We set up the server, backups and sign-in so your IT team signs off on day one."}, {"name": "Data migration from your current tools", "value": 100000, "why": "Projects, tasks and finance sheets imported safely."}, {"name": "Priority update channel", "value": 60000, "why": "Fixes and features reach you the same week they ship."}]'::jsonb,
      'Seven-day install guarantee: running on your server within 7 days of access, or 50 percent off the first year.', 'We certify four self-hosted installs a quarter.', 'Licences signed in 2026 keep this year''s price on renewal for three years.', '{"magnet": "Self-Hosted", "avatar": "Pulse", "goal": "Your data on your server, always up to date", "interval": "in 7 days", "container": "Licence", "tagline": "Pulse Self-Hosted: your company OS on your server, live in 7 days."}'::jsonb, '[{"label": "Building an internal tool team for one year", "amount": 4800000}, {"label": "Enterprise HRMS + project + finance suite, 100 seats (per year)", "amount": 1800000}]'::jsonb, 'INR', 600000,
      'year', 'For companies that cannot put their work data in someone else''s cloud, Pulse Self-Hosted gives them the whole company OS on their own server, with the same updates as the hosted Pulse. Already running at Atlas Crest.', 'Serious and trustworthy. Lead with data ownership and the live release check. Show the licence register and the update command.', '[{"key": "standard", "name": "Standard", "price": 600000, "seats": 50, "blurb": "Up to 50 people on your own server.", "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications", "processes-library", "process-builder", "runs", "my-steps", "sop-import", "clients-crm", "contacts", "delivery-workbench", "client-portal", "media-review", "asset-tracker", "designers-board", "team-dashboard", "outcomes", "task-review", "billing-documents", "finance-overview", "hr-desk", "payroll", "ai-employees", "updates-feed", "role-briefs", "self-hosted", "module-switches", "screens-per-role", "company-setup", "data-import"]}, {"key": "enterprise", "name": "Enterprise", "price": 1500000, "seats": 200, "blurb": "Connectors, API, sealed data and priority updates.", "highlight": true, "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications", "processes-library", "process-builder", "runs", "my-steps", "sop-import", "clients-crm", "contacts", "delivery-workbench", "client-portal", "media-review", "asset-tracker", "designers-board", "team-dashboard", "outcomes", "task-review", "billing-documents", "finance-overview", "hr-desk", "payroll", "ai-employees", "updates-feed", "role-briefs", "self-hosted", "module-switches", "screens-per-role", "company-setup", "data-import", "api-v1", "webhooks", "partner-agent-api", "sealed-documents", "company-connectors", "drive-sync", "org-switcher", "licences-register", "leadership-people", "people-cost", "ca-desk"]}, {"key": "partner", "name": "Partner", "price": null, "seats": null, "blurb": "White-label Pulse for your own clients. Priced per partner.", "features": ["focus-home", "my-desk", "tasks-views", "projects", "team-chats", "chat-tasks", "pip-assistant", "team-directory", "auto-attendance", "leave-shifts", "phone-app", "desktop-app", "push-notifications", "roles-permissions", "sign-in-security", "audit-log", "command-search", "smart-notifications", "processes-library", "process-builder", "runs", "my-steps", "sop-import", "clients-crm", "contacts", "delivery-workbench", "client-portal", "media-review", "asset-tracker", "designers-board", "team-dashboard", "outcomes", "task-review", "billing-documents", "finance-overview", "hr-desk", "payroll", "ai-employees", "updates-feed", "role-briefs", "self-hosted", "module-switches", "screens-per-role", "company-setup", "data-import", "api-v1", "webhooks", "partner-agent-api", "sealed-documents", "company-connectors", "drive-sync", "org-switcher", "licences-register", "leadership-people", "people-cost", "ca-desk", "start-own-pulse", "portable-profile", "industry-packs", "developers-page", "pulse-network"]}]'::jsonb, '#1f9d55', 2, true, v_person);
