  if not exists (select 1 from pulse.hq_idea) then
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'Self-serve trial with sample data', 'Prospects cannot feel Pulse before a call. A trial organisation pre-filled with an industry pack and realistic sample data would let them click through their own week.', 'Founders evaluating Pulse', 5, 3, 'planned', array['company-setup', 'industry-packs', 'start-own-pulse']::text[], true, v_person, now() - interval '0 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'A signed offer opens the customer''s Pulse', 'Between "yes" and "live" there is a gap of emails and calls. When an offer is accepted, open the organisation, apply the pack and invite the founder automatically.', 'New customers and our onboarding team', 5, 3, 'exploring', array['start-own-pulse', 'industry-packs', 'licences-register']::text[], true, v_person, now() - interval '1 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'Investor and board view', 'Founders rebuild the same slide every month. One read-only page per organisation with delivery, people, cash and growth, shareable by link.', 'Founders reporting to investors or a board', 4, 2, 'new', array['focus-home', 'finance-overview', 'leadership-people']::text[], true, v_person, now() - interval '2 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'Per-task pricing for AI employees', 'Seat pricing undercounts the value of AI employees. Charge per completed task, with a monthly cap, so customers start small and grow.', 'Customers adopting AI employees', 4, 2, 'new', array['ai-employees']::text[], true, v_person, now() - interval '3 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'Industry pack marketplace', 'Every new industry needs its processes built once. Let partners publish packs (solar, real estate, clinics) and earn when others install them.', 'Consultants and partners', 4, 4, 'new', array['industry-packs', 'processes-library']::text[], true, v_person, now() - interval '4 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'WhatsApp client chat through the business number', 'Clients will not leave WhatsApp. Let the team answer client WhatsApp messages from Pulse, kept with the client''s record.', 'Client-facing teams', 5, 4, 'exploring', array['whatsapp-client-chat', 'team-chats', 'clients-crm']::text[], true, v_person, now() - interval '5 minutes');
    insert into pulse.hq_idea(org_id, title, problem, for_whom, impact, effort, status, feature_keys, draft, created_by, created_at)
    values (v_org, 'Pulse Academy for operators', 'Customers need someone inside who runs Pulse well. A short certified course for operations managers creates champions and a hiring pool.', 'Operations managers at customers', 3, 3, 'parked', array['processes-library', 'process-builder']::text[], true, v_person, now() - interval '6 minutes');
  end if;
  insert into pulse.hq_brand(org_id, body, updated_by) values (v_org, '{"draft": true, "tagline": "The operating system for teams that deliver.", "oneLiner": "Pulse runs a service company end to end, from work, people and money to clients and AI employees, in one calm app on our cloud or your own server.", "category": "Company operating system for service businesses", "forWho": "Founders of service businesses with 15 to 300 people: agencies, installers, real-estate marketers and consultancies, in India first.", "against": "The eight-tool stack: WhatsApp groups, sheets, a project tool nobody updates, an HRMS, Tally exports and a founder chasing everyone.", "promise": "Know what is happening, who is doing it and whether it makes money, without asking.", "pillars": ["One place for work, people, money and clients", "Processes that run themselves, step by step", "AI employees that take tasks and report back in chat", "Your data, your server, your brand"], "proof": ["Runs Estate Autopilots every day, from attendance to invoices", "Self-hosted at Atlas Crest on their own server", "Industry packs for agencies, solar installers and real estate", "Every feature backed by the product itself: see the catalogue"], "voice": "Calm, plain and confident. Short sentences. Benefits before features. No jargon, no hype, no exclamation marks.", "pricing": "Per company, in tiers by seats, never per-feature add-ons. Hosted plans billed monthly in INR; self-hosted licences billed yearly. A one-time launch fee covers setup and is protected by each offer''s guarantee.", "colours": ["#6b4cf0", "#ffd43b", "#1d1d1f", "#f5f5f7"]}'::jsonb, v_person) on conflict (org_id) do nothing;
  perform set_config('pulse.org_id', '', true);
